                ctx.ellipse(0, 1.4, 6.9, 10.8, 0, Math.PI * 1.08, Math.PI * 1.92);
                ctx.strokeStyle = 'rgba(200, 229, 246, 0.52)';
                ctx.lineWidth = 0.8;
                ctx.stroke();
                this.oval(ctx, 0, -0.1, 2.2, 5.2, '#243659', '#1c2c4a');
                this.oval(ctx, 0, 11.1, 4.1, 2.6, '#c3e5ef');
