                ctx.quadraticCurveTo(0, 15, 7, 8);
                ctx.strokeStyle = 'rgba(73, 99, 142, 0.72)';
                ctx.lineWidth = 0.7;
                ctx.stroke();
                this.oval(ctx, -3.2, -5.4, 2.3, 2.7, '#fffdf9');
                ctx.beginPath();
                ctx.ellipse(-3.2, -5.4, 2.3, 2.7, 0, 0, Math.PI * 2);
